@st.cache_data(show_spinner=False)
def load_table(name: str) -> pd.DataFrame:
    path = DATA_DIR / f"{name}.csv.gz"
    if not path.exists():
        return pd.DataFrame()
    return pd.read_csv(path, low_memory=False, compression="gzip")


@st.cache_data(show_spinner=False)
def audited_company_spill_trends() -> pd.DataFrame:
    """Return workbook-audited annual spill totals with exported duration context."""
    rows = [
        {
            "water_company_name": company,
            "reporting_year": year,
            "counted_spills": counted_spills,
        }
        for company, yearly_values in AUDITED_COMPANY_ANNUAL_SPILLS.items()
        for year, counted_spills in yearly_values.items()
    ]
    audited = pd.DataFrame(rows)

    exported = load_table("company_spill_trends")
    duration_columns = {
        "water_company_name",
        "reporting_year",
        "spill_duration_hours",
    }
    if duration_columns.issubset(exported.columns):
        durations = exported[list(duration_columns)].copy()
        durations["reporting_year"] = pd.to_numeric(
            durations["reporting_year"], errors="coerce"
        )
        audited = audited.merge(
            durations,
            on=["water_company_name", "reporting_year"],
            how="left",
            validate="one_to_one",
        )
    return audited.sort_values(["water_company_name", "reporting_year"]).reset_index(drop=True)


def audited_company_spill_summary() -> pd.DataFrame:
    """Rank companies by counted spills across the complete observed period."""
    trends = audited_company_spill_trends()
    summary = (
        trends.groupby("water_company_name", as_index=False)["counted_spills"]
        .sum(min_count=1)
        .rename(columns={"counted_spills": "total_counted_spills_2021_2025"})
        .sort_values("total_counted_spills_2021_2025", ascending=False)
        .reset_index(drop=True)
    )
    summary.insert(0, "spill_rank_2021_2025", np.arange(1, len(summary) + 1))
    return summary


@st.cache_resource(show_spinner=False)
def load_model_bundle():
    path = ARTIFACT_DIR / "final_trained_2026_forecast_model.joblib"
    return joblib.load(path)


@st.cache_data(show_spinner=False)
def load_input_metadata():
    with open(ARTIFACT_DIR / "input_metadata.json", encoding="utf-8") as handle:
        return json.load(handle)


def pretty(value) -> str:
    return str(value).replace("_", " ").strip().title()


def safe_text(value, fallback="Not available") -> str:
    if value is None or pd.isna(value) or str(value).strip() == "":
        return html.escape(fallback)
    return html.escape(str(value).strip())


def value_text(value, decimals=0, suffix="") -> str:
    numeric = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if pd.isna(numeric):
        return "Not available"
    return f"{float(numeric):,.{decimals}f}{suffix}"


def available_values(frame: pd.DataFrame, column: str) -> list[str]:
    if frame.empty or column not in frame.columns:
        return []
    return sorted(
        frame[column].dropna().astype(str).str.strip().loc[lambda s: s.ne("")].unique().tolist()
    )


def first_existing(frame: pd.DataFrame, candidates: list[str]) -> str | None:
    return next((column for column in candidates if column in frame.columns), None)



UPLOAD_HIGH_SPILL_THRESHOLD = 80
UPLOAD_HIGH_DURATION_THRESHOLD_HOURS = 400
UPLOAD_LOW_SPILL_THRESHOLD = 20
UPLOAD_LOW_DURATION_THRESHOLD_HOURS = 100

UPLOAD_COLUMN_ALIASES = {
    "water_company_name": [
        "water_company_name",
        "Water Company Name",
        "water company",
        "company",
        "operator",
    ],
    "reporting_year": [
        "reporting_year",
        "Reporting Year",
        "year",
        "report year",
    ],
    "counted_spills": [
        "counted_spills",
        "Counted spills using 12-24h count method",
        "counted spills",
        "spill count",
        "spills",
    ],
    "total_duration_hours": [
        "total_duration_hours",
        "Total Duration (hh:mm:ss) all spills prior to processing through 12-24h count method",
        "total duration",
        "duration hours",
        "spill duration hours",
        "duration",
    ],
    "site_name": [
        "site_name",
        "Site Name (EA Consents Database)",
        "site name",
        "ea site name",
        "asset name",
    ],
    "permit_reference": [
        "permit_reference",
        "EA Permit Reference (EA Consents Database)",
        "permit reference",
        "permit",
    ],
    "activity_reference": [
        "activity_reference",
        "Activity Reference on Permit",
        "activity reference",
    ],
    "outlet_ngr": [
        "outlet_ngr",
        "Outlet Discharge NGR (EA Consents Database)",
        "national grid reference",
        "ngr",
        "grid reference",
    ],
    "receiving_water": [
        "receiving_water",
        "Receiving Water / Environment (common name) (EA Consents Database)",
        "receiving water",
        "water environment",
    ],
    "existing_risk_category": [
        "label",
        "Label",
        "risk_category",
        "risk category",
        "existing risk category",
    ],
}


def normalised_column_name(value) -> str:
    """Normalise a heading so uploaded files can use common naming variants."""

    return re.sub(r"[^a-z0-9]+", "_", str(value).casefold()).strip("_")


def resolve_upload_columns(frame: pd.DataFrame) -> dict[str, str]:
    """Match uploaded annual-return headings to the dashboard risk formula."""

    available = {normalised_column_name(column): column for column in frame.columns}
    resolved: dict[str, str] = {}
    for key, aliases in UPLOAD_COLUMN_ALIASES.items():
        for alias in aliases:
            source = available.get(normalised_column_name(alias))
            if source is not None:
                resolved[key] = source
                break

    required = {
        "water_company_name",
        "reporting_year",
        "counted_spills",
        "total_duration_hours",
    }
    missing = sorted(required.difference(resolved))
    if missing:
        readable = ", ".join(pretty(column) for column in missing)
        expected = {pretty(key): UPLOAD_COLUMN_ALIASES[key][0] for key in missing}
        raise KeyError(
            f"Missing required annual-return columns: {readable}. "
            f"Expected headings similar to: {json.dumps(expected)}"
        )
    return resolved


def parse_duration_hours(value) -> float:
    """Convert annual-return duration values to hours."""

    if value is None or pd.isna(value):
        return np.nan
    if isinstance(value, pd.Timedelta):
        return value.total_seconds() / 3600
    if isinstance(value, timedelta):
        return value.total_seconds() / 3600
    if isinstance(value, (datetime, time)):
        return value.hour + value.minute / 60 + value.second / 3600
    if isinstance(value, (int, float, np.integer, np.floating)):
        return float(value)

    text_value = str(value).strip().replace(",", "")
    if not text_value:
        return np.nan
    try:
        return float(text_value)
    except ValueError:
        pass

    match = re.fullmatch(r"(\d+):(\d{1,2})(?::(\d{1,2}(?:\.\d+)?))?", text_value)
    if match:
        hours = float(match.group(1))
        minutes = float(match.group(2))
        seconds = float(match.group(3) or 0)
        if minutes < 60 and seconds < 60:
            return hours + minutes / 60 + seconds / 3600

    parsed = pd.to_timedelta(text_value, errors="coerce")
    return np.nan if pd.isna(parsed) else parsed.total_seconds() / 3600


def numeric_upload_series(series: pd.Series) -> pd.Series:
    """Read numbers from annual-return columns that may contain commas."""

    if pd.api.types.is_numeric_dtype(series):
        return pd.to_numeric(series, errors="coerce")
    cleaned = series.astype("string").str.replace(",", "", regex=False).str.strip()
    return pd.to_numeric(cleaned, errors="coerce")


def calculate_uploaded_risk_categories(frame: pd.DataFrame) -> pd.Series:
    """Apply the audited EDM risk-category formula to uploaded annual returns."""

    duration = pd.to_numeric(frame["total_duration_hours"], errors="coerce")
    spills = pd.to_numeric(frame["counted_spills"], errors="coerce")
    valid = duration.notna() & spills.notna()

    categories = pd.Series("Uncategorised", index=frame.index, dtype="string")
    categories.loc[valid] = "Medium"
    categories.loc[
        valid
        & spills.gt(UPLOAD_HIGH_SPILL_THRESHOLD)
        & duration.gt(UPLOAD_HIGH_DURATION_THRESHOLD_HOURS)
    ] = "High"
    categories.loc[
        valid
        & spills.lt(UPLOAD_LOW_SPILL_THRESHOLD)
        & duration.lt(UPLOAD_LOW_DURATION_THRESHOLD_HOURS)
    ] = "Low"
    return categories


def prepare_uploaded_edm_returns(raw: pd.DataFrame) -> tuple[pd.DataFrame, dict[str, str]]:
    """Clean uploaded EDM annual returns and calculate risk categories."""

    if raw.empty:
        raise ValueError("The uploaded annual-return file is empty.")

    columns = resolve_upload_columns(raw)
    result = pd.DataFrame(index=raw.index)
    result["source_row"] = np.arange(2, len(raw) + 2)
    result["water_company_name"] = (
        raw[columns["water_company_name"]]
        .astype("string")
        .str.strip()
        .fillna("Unknown company")
        .replace("", "Unknown company")
    )
    result["reporting_year"] = (
        numeric_upload_series(raw[columns["reporting_year"]]).round().astype("Int64")
    )
    result["counted_spills"] = numeric_upload_series(raw[columns["counted_spills"]])
    result["total_duration_hours"] = raw[columns["total_duration_hours"]].map(
        parse_duration_hours
    )

    optional_columns = {
        "site_name": "site_name",
        "permit_reference": "permit_reference",
        "activity_reference": "activity_reference",
        "outlet_ngr": "outlet_ngr",
        "receiving_water": "receiving_water",
    }
    for output_column, key in optional_columns.items():
        source = columns.get(key)
        result[output_column] = (
            raw[source].astype("string").str.strip().fillna("") if source else ""
        )

    result["calculated_risk_category"] = calculate_uploaded_risk_categories(result)

    source_label = columns.get("existing_risk_category")
    if source_label:
        uploaded_label = raw[source_label].astype("string").str.strip().str.title()
        result["uploaded_existing_risk_category"] = uploaded_label.where(
            uploaded_label.isin(RISK_ORDER),
            "Uncategorised",
        )
        result["existing_label_matches_formula"] = result[
            "uploaded_existing_risk_category"
        ].eq(result["calculated_risk_category"])

    def issue_text(row: pd.Series) -> str:
        issues = []
        if pd.isna(row["reporting_year"]):
            issues.append("Missing reporting year")
        if pd.isna(row["counted_spills"]):
            issues.append("Missing counted spills")
        if pd.isna(row["total_duration_hours"]):
            issues.append("Missing duration")
        return "; ".join(issues) if issues else "Ready"

    result["quality_check"] = result.apply(issue_text, axis=1)
    return result.reset_index(drop=True), columns

def coalesced_text(
    frame: pd.DataFrame,
    candidates: list[str],
    fallback: str = "Not recorded",
) -> pd.Series:
    """Return the first meaningful text value across candidate columns."""

    result = pd.Series(pd.NA, index=frame.index, dtype="string")
    missing_markers = {
        "",
        "nan",
        "none",
        "null",
        "<na>",
        "n/a",
        "not available",
        "not recorded",
    }

    for column in candidates:
        if column not in frame.columns:
            continue
        values = frame[column].astype("string").str.strip()
        valid = values.notna() & ~values.str.lower().isin(missing_markers)
        result = result.mask(result.isna() & valid, values)

    return result.fillna(fallback)


def priority_location_key(frame: pd.DataFrame) -> pd.Series:
    """Create a stable key for joining forecast rows to observed locations."""

    location_column = first_existing(frame, ["location_id", "Location ID"])
    if location_column:
        key = frame[location_column].astype("string").str.strip()
        return key.mask(key.eq("") | key.str.lower().isin(["nan", "none", "<na>"]))

    company_column = first_existing(
        frame,
        ["water_company_name", "company", "water_company"],
    )
    outlet_column = first_existing(
        frame,
        ["parsed_grid_reference", "outlet_ngr", "source_outlet_ngr"],
    )
    if not company_column or not outlet_column:
        return pd.Series(pd.NA, index=frame.index, dtype="string")

    company = frame[company_column].astype("string").str.strip()
    outlet = frame[outlet_column].astype("string").str.strip()
    key = company + "__" + outlet
    invalid = company.isna() | outlet.isna() | company.eq("") | outlet.eq("")
    return key.mask(invalid)


def add_observed_priority_context(
    priority_frame: pd.DataFrame,
    observed_frame: pd.DataFrame,
) -> pd.DataFrame:
    """Fill historical and destination context on recorded or forecast rows."""

    result = priority_frame.copy()
    if result.empty or observed_frame.empty:
        return result

    result_key = priority_location_key(result)
    observed = observed_frame.copy()
    observed["_priority_context_key"] = priority_location_key(observed)

    context_columns = [
        "risk_history",
        "years_observed",
        "receiving_water",
        "source_receiving_water",
        "source_receiving_water_environment_common_name_ea_consents_database",
        "wasc_site_name",
        "source_site_name_wasc_operational",
        "source_site_name_wasc_operational_optional",
        "site_name_wasc_operational_optional",
        "site_name_wasc_operational",
        "site_name",
        "source_site_name_ea_consents_database",
    ]
    missing_markers = {
        "",
        "nan",
        "none",
        "null",
        "<na>",
        "n/a",
        "not available",
        "not recorded",
    }

    for column in context_columns:
        if column not in observed.columns:
            continue

        source_values = observed[column].astype("string").str.strip()
        valid = (
            observed["_priority_context_key"].notna()
            & source_values.notna()
            & ~source_values.str.lower().isin(missing_markers)
        )
        lookup = (
            pd.DataFrame(
                {
                    "key": observed.loc[valid, "_priority_context_key"],
                    "value": source_values.loc[valid],
                }
            )
            .drop_duplicates("key")
            .set_index("key")["value"]
        )
        mapped = result_key.map(lookup)

        if column not in result.columns:
            result[column] = mapped
        else:
            existing = result[column].astype("string").str.strip()
            existing_valid = (
                existing.notna()
                & ~existing.str.lower().isin(missing_markers)
            )
            result[column] = existing.where(existing_valid, mapped)

    return result


def prepare_priority_context(
    priority_frame: pd.DataFrame,
    observed_frame: pd.DataFrame,
) -> pd.DataFrame:
    """Add consistent year, receiving-water and treatment-site fields."""

    result = add_observed_priority_context(priority_frame, observed_frame)
    if result.empty:
        return result

    result["_priority_receiving_water"] = coalesced_text(
        result,
        [
            "receiving_water",
            "source_receiving_water",
            "source_receiving_water_environment_common_name_ea_consents_database",
        ],
    )
    result["_priority_treatment_site"] = coalesced_text(
        result,
        [
            "wasc_site_name",
            "source_site_name_wasc_operational",
            "source_site_name_wasc_operational_optional",
            "site_name_wasc_operational_optional",
            "site_name_wasc_operational",
        ],
    )
    result["_priority_discharge_site"] = coalesced_text(
        result,
        [
            "site_name",
            "source_site_name_ea_consents_database",
            "ea_site_name",
        ],
    )
    result["_priority_high_risk_year_values"] = result.apply(
        recorded_high_risk_years,
        axis=1,
    )
    result["_priority_high_risk_year_count"] = result[
        "_priority_high_risk_year_values"
    ].map(len)
    result["_priority_high_risk_year_streak"] = result[
        "_priority_high_risk_year_values"
    ].map(longest_consecutive_year_run)
    result["_priority_high_risk_years"] = result[
        "_priority_high_risk_year_values"
    ].map(
        lambda years: ", ".join(map(str, years))
        if years
        else "Not available"
    )
    return result


def recorded_high_risk_years(row: pd.Series) -> tuple[int, ...]:
    """Extract years recorded as High from history text or annual columns."""

    years = set()
    history = str(row.get("risk_history", ""))
    years.update(
        int(year)
        for year in re.findall(
            r"\b(20\d{2})\s*:\s*High\b",
            history,
            flags=re.IGNORECASE,
        )
    )

    for column, value in row.items():
        normalised_column = re.sub(r"[^a-z0-9]+", "_", str(column).lower()).strip("_")
        match = re.fullmatch(
            r"(?:risk|risk_category|period_risk_category)_(20\d{2})",
            normalised_column,
        )
        if match and str(value).strip().lower() == "high":
            years.add(int(match.group(1)))

    return tuple(sorted(years))


def longest_consecutive_year_run(years: tuple[int, ...]) -> int:
    """Return the longest uninterrupted run in an ordered collection of years."""

    ordered_years = sorted(set(int(year) for year in years))
    if not ordered_years:
        return 0

    longest = 1
    current = 1
    for previous, current_year in zip(ordered_years, ordered_years[1:]):
        if current_year == previous + 1:
            current += 1
        else:
            current = 1
        longest = max(longest, current)
    return longest


def combined_year_text(values: pd.Series) -> str:
    years = sorted(
        {
            int(year)
            for value in values.dropna().astype(str)
            for year in re.findall(r"\b20\d{2}\b", value)
        }
    )
    return ", ".join(map(str, years)) if years else "Not available"


def count_years_in_text(value) -> int:
    return len(set(re.findall(r"\b20\d{2}\b", str(value))))


def count_recorded_values(values: pd.Series) -> int:
    cleaned = values.astype("string").str.strip()
    return int(
        cleaned.loc[
            cleaned.notna()
            & ~cleaned.str.lower().isin(
                ["", "nan", "none", "<na>", "not available", "not recorded"]
            )
        ].nunique()
    )


def make_risk_ranking(
    frame: pd.DataFrame,
    risk_column: str,
    group_column: str | None,
) -> pd.DataFrame:
    """Create a plain-English ranking for the current map view."""
    if frame.empty or not group_column or group_column not in frame.columns:
        return pd.DataFrame()

    working = frame.loc[
        frame[risk_column].isin(RISK_ORDER)
        & frame[group_column].notna()
    ].copy()
    working[group_column] = working[group_column].astype(str).str.strip()
    working = working.loc[working[group_column].ne("")]
    if working.empty:
        return pd.DataFrame()

    counts = (
        working.groupby([group_column, risk_column])
        .size()
        .unstack(fill_value=0)
        .reindex(columns=RISK_ORDER, fill_value=0)
        .reset_index()
    )
    counts["Mapped locations"] = counts[RISK_ORDER].sum(axis=1)

    spill_column = first_existing(
        working,
        [
            "place_total_counted_spills",
            "total_counted_spills_in_period",
            "counted_spills",
        ],
    )
    if spill_column:
        spill_values = working.assign(
            _spill_value=pd.to_numeric(working[spill_column], errors="coerce")
        )
        spill_group = spill_values.groupby(group_column, as_index=False)["_spill_value"]
        # Place totals are repeated on every outlet in the same place, whereas
        # outlet totals need summing for a water-company ranking.
        spills = (
            spill_group.max()
            if spill_column == "place_total_counted_spills"
            else spill_group.sum(min_count=1)
        ).rename(columns={"_spill_value": "Recorded spills"})
        counts = counts.merge(spills, on=group_column, how="left")
    else:
        counts["Recorded spills"] = np.nan

    counts["Risk score"] = (
        counts["High"] * 3
        + counts["Medium"] * 2
        + counts["Low"]
    )
    counts = counts.sort_values(
        ["High", "Medium", "Recorded spills", "Mapped locations", group_column],
        ascending=[False, False, False, False, True],
        na_position="last",
    ).reset_index(drop=True)
    counts.insert(0, "Rank", np.arange(1, len(counts) + 1))
    return counts


def render_rank_list(
    ranking: pd.DataFrame,
    name_column: str,
    empty_message: str,
    limit: int = 8,
):
    if ranking.empty:
        st.info(empty_message)
        return

    rows = []
    for _, row in ranking.head(limit).iterrows():
        colour = (
            RISK_COLOURS["High"] if int(row.get("High", 0)) > 0
            else RISK_COLOURS["Medium"] if int(row.get("Medium", 0)) > 0
            else RISK_COLOURS["Low"]
        )
        spills = row.get("Recorded spills")
        spill_text = (
            f" · {float(spills):,.0f} recorded spills"
            if pd.notna(spills)
            else ""
        )
        rows.append(
            f"""
            <div class="edm-rank-row" style="--rank-colour:{colour};">
              <div><span class="edm-rank-number">{int(row['Rank'])}</span>
              <span class="edm-rank-name">{html.escape(str(row[name_column]))}</span></div>
              <div class="edm-rank-detail">
                ▲ High {int(row.get('High', 0)):,} &nbsp; ◆ Medium {int(row.get('Medium', 0)):,}
                &nbsp; ● Low {int(row.get('Low', 0)):,}{spill_text}
              </div>
            </div>
            """
        )
    st.html("".join(rows))


